int dir_empty(const char *path)
{
  struct dirent *ent;
  int ret = 1;

  DIR *d = opendir(path);
  if (!d) {
    fprintf(stderr, "%s: ", path);
    perror("");
    return -1;
  }

  while ((ent = readdir(d))) {
    if (!strcmp(ent->d_name, ".") || !(strcmp(ent->d_name, "..")))
      continue;
    ret = 0;
    break;
  }

  closedir(d);
  return ret;
}

